create table public.weather_records (id uuid primary key default gen_random_uuid(), latitude double precision not null, longitude double precision not null, temperature numeric, humidity numeric, rainfall numeric, wind_speed numeric, weather_condition text, forecast_time timestamptz not null, provider text not null, created_at timestamptz not null default now());
create table public.crop_recommendations (id uuid primary key default gen_random_uuid(), farmer_id uuid not null references public.profiles(id) on delete cascade, plot_id uuid references public.land_plots(id) on delete set null, crop_name text not null, suitability_score numeric, recommendation_reason text, planting_window text, harvesting_window text, estimated_yield numeric, estimated_market_price numeric, estimated_expenses numeric, estimated_revenue numeric, estimated_profit numeric, confidence_level text not null, data_sources jsonb not null default '[]', generated_at timestamptz not null default now());
create table public.fertilizer_recommendations (id uuid primary key default gen_random_uuid(), plot_id uuid not null references public.land_plots(id) on delete cascade, crop_allocation_id uuid references public.crop_allocations(id) on delete set null, fertilizer_name text not null, fertilizer_category text not null, recommended_quantity numeric, quantity_unit text, estimated_cost numeric, application_date date, application_instructions text, source text not null, verification_status text not null, created_at timestamptz not null default now());
create table public.harvest_records (id uuid primary key default gen_random_uuid(), farmer_id uuid not null references public.profiles(id) on delete cascade, plot_id uuid references public.land_plots(id) on delete set null, crop_name text not null, harvest_date date not null, harvested_quantity numeric not null check (harvested_quantity >= 0), quantity_unit text not null, yield_quality text, notes text, created_at timestamptz not null default now());
create table public.notifications (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, title text not null, message text not null, notification_type text not null, is_read boolean not null default false, created_at timestamptz not null default now());
create index weather_location_time_idx on public.weather_records(latitude, longitude, forecast_time desc); create index recommendations_farmer_idx on public.crop_recommendations(farmer_id, generated_at desc); create index notifications_user_idx on public.notifications(user_id, is_read, created_at desc);
create or replace function public.enforce_plot_allocation_limit() returns trigger language plpgsql as $$ declare plot_area numeric; used_area numeric; begin select total_area_acres into plot_area from public.land_plots where id = new.plot_id for update; select coalesce(sum(allocated_area_acres),0) into used_area from public.crop_allocations where plot_id = new.plot_id and id <> coalesce(new.id, '00000000-0000-0000-0000-000000000000'::uuid); if plot_area is null then raise exception 'plot not found'; end if; if used_area + new.allocated_area_acres > plot_area then raise exception 'allocation exceeds plot area'; end if; return new; end; $$;
create trigger crop_allocation_limit before insert or update of plot_id, allocated_area_acres on public.crop_allocations for each row execute procedure public.enforce_plot_allocation_limit();
alter table public.weather_records enable row level security; alter table public.crop_recommendations enable row level security; alter table public.fertilizer_recommendations enable row level security; alter table public.harvest_records enable row level security; alter table public.notifications enable row level security;
create policy "private recommendations" on public.crop_recommendations for all using (farmer_id = auth.uid()) with check (farmer_id = auth.uid()); create policy "private harvests" on public.harvest_records for all using (farmer_id = auth.uid()) with check (farmer_id = auth.uid()); create policy "private notifications" on public.notifications for all using (user_id = auth.uid()) with check (user_id = auth.uid());
